fn sh27_ui_int_in_kab() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let l = std::fs::read_to_string(root.join("lib/kab/ui/ui_int.kab")).expect("ui_int.kab");
    assert!(
        l.contains("pub fn uiIsInt") && l.contains("\"int\""),
        "SH27 Kab uiIsInt"
    );
}

